        try: data=json.load(open(finished)); print("ROLLOUT_FINISHED",finished,json.dumps(data,separators=(",",":")),flush=True)
        except (OSError,ValueError) as e: print("ROLLOUT_FINISHED_READ_ERROR",finished,type(e).__name__,flush=True)
        sys.exit(0)
